bool write_all(int fd, const char* buf, size_t n) {
  while (n > 0) {
    ssize_t w = write(fd, buf, n);
    if (w < 0) {
      if (errno == EINTR) continue;  // interrupted before writing anything
      return false;                  // real error (EPIPE, ENOSPC, ...)
    }
    buf += w;
    n -= static_cast<size_t>(w);
  }
  return true;
}
